import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Store, ChevronDown, Plus, UserCircle, LogOut } from 'lucide-react';

// Dropdown store switcher
function StoreSwitcher() {
  const { availableStores, storeId, switchStore } = useAuth();
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();

  if (availableStores.length <= 1) return null;

  const current = availableStores.find(s => s.id === storeId) || availableStores[0];
  return (
    <div className="relative">
      <button onClick={() => setOpen(!open)} className="flex items-center gap-2 px-3 py-1.5 bg-gray-100 rounded-lg">
        <Store size={16} />
        <span className="text-sm truncate max-w-[120px]">{current?.name}</span>
        <ChevronDown size={14} />
      </button>
      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div className="absolute right-0 mt-2 w-56 bg-white rounded-lg shadow-lg border z-50">
            <div className="p-2">
              {availableStores.map(s => (
                <button
                  key={s.id}
                  onClick={() => { switchStore(s.id); setOpen(false); }}
                  className={`w-full text-left px-3 py-2 rounded-lg text-sm hover:bg-gray-100 flex justify-between ${s.id === storeId ? 'bg-green-50 text-green-700' : ''}`}
                >
                  <span className="truncate">{s.name}</span>
                  {s.id === storeId && <span>✓</span>}
                </button>
              ))}
              <hr className="my-2" />
              <button
                onClick={() => { navigate('/app/settings'); setOpen(false); }}
                className="w-full text-left px-3 py-2 rounded-lg text-sm text-blue-600 hover:bg-blue-50 flex items-center gap-2"
              >
                <Plus size={14} /> Add New Store
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

export default function Layout() {
  const { staff, signOut } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  // Determine current page title from the path
  const pageTitles = {
    '/app': 'Dashboard',
    '/app/pos': 'POS',
    '/app/inventory': 'Inventory',
    '/app/sales': 'Sales',
    '/app/reports': 'Reports',
    '/app/employees': 'Employees',
    '/app/returns': 'Returns',
    '/app/return-history': 'Return History',
    '/app/settings': 'Settings',
    '/app/discounts': 'Discounts',
    '/app/profile': 'Profile',
    '/app/layby': 'Lay‑by',
    '/app/invoices': 'Invoices',
  };
  const currentTitle = pageTitles[location.pathname] || 'Bwanali POS';

  return (
    <div className="h-screen flex flex-col bg-gray-50 overflow-hidden">
      {/* Top Header */}
      <header className="bg-white shadow-sm border-b px-4 py-3 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-3">
          {/* Clickable store name -> Dashboard */}
          <button
            onClick={() => navigate('/app')}
            className="text-lg font-bold text-green-700 truncate hover:underline"
          >
            {staff?.store?.name || 'Bwanali POS'}
          </button>
          <span className="hidden sm:inline text-gray-400">|</span>
          <span className="hidden sm:inline text-sm text-gray-600 truncate">{currentTitle}</span>
        </div>
        <div className="flex items-center gap-3">
          <StoreSwitcher />
          <button
            onClick={() => navigate('/app/profile')}
            className="flex items-center gap-1 px-2 py-1 rounded-lg hover:bg-gray-100 text-sm"
          >
            <UserCircle size={16} />
            <span className="hidden sm:inline truncate max-w-[100px]">{staff?.full_name}</span>
          </button>
          <button
            onClick={async () => { await signOut(); navigate('/login'); }}
            className="flex items-center gap-1 px-2 py-1 rounded-lg text-red-600 hover:bg-red-50 text-sm"
          >
            <LogOut size={16} />
            <span className="hidden sm:inline">Logout</span>
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-auto">
        <Outlet />
      </main>
    </div>
  );
}
